const plain = text => ({ t: 'example', label: 'Простыми словами', text })
const grid = (a, b, n) => Array.from({ length: n + 1 }, (_, i) => a + ((b - a) * i) / n)

// Прямая w₁x₁ + w₂x₂ + b = k на отрезке [a, b] по x₁
const levelLine = (m, k, a, z) => grid(a, z, 2).map(x => [x, (k - m.b - m.w[0] * x) / m.w[1]])
// Решающая функция RBF-SVM: f(x) = Σ αᵢyᵢ·exp(−γ‖x − xᵢ‖²) + b
const rbf = m => p => m.sv.reduce((s, v, i) => s + m.a[i] * Math.exp(-m.gamma * ((p[0] - v[0]) ** 2 + (p[1] - v[1]) ** 2)), m.b)
const cells = (f, box, step) => {
  const out = []
  for (let x = box[0] + step / 2; x < box[1]; x += step) {
    for (let y = box[2] + step / 2; y < box[3]; y += step) out.push([x, y, f([x, y]) > 0 ? 1 : 0])
  }
  return out
}

const HARD_BOX = [-2.5, 3.2, -2.8, 2.8]
const SOFT_BOX = [-3.2, 3.4, -3.2, 3]
const CIRC_BOX = [-1.5, 1.5, -1.5, 1.5]
const MOONS_BOX = [-1.6, 2.6, -1.2, 1.7]

// Линейный SVM: точки, разделяющая прямая (сплошная), границы полосы (пунктир), опорные векторы (кольца)
const linearPlot = (m, c0, c1, box, caption) => ({ t: 'plot', caption, equal: true, axesAtZero: false, legend: false, height: 360,
  x: { min: box[0], max: box[1], step: 1, label: 'x₁' }, y: { min: box[2], max: box[3], step: 1, label: 'x₂' },
  series: [
    { type: 'line', points: levelLine(m, 0, box[0], box[1]), color: 'gray', width: 2.4 },
    { type: 'line', points: levelLine(m, 1, box[0], box[1]), color: 'orange', width: 1.6, dash: true },
    { type: 'line', points: levelLine(m, -1, box[0], box[1]), color: 'blue', width: 1.6, dash: true },
    { type: 'scatter', points: c0, color: 'blue', r: 4, opacity: 1, stroke: '#0B0B0E' },
    { type: 'scatter', points: c1, color: 'orange', r: 4, opacity: 1, stroke: '#0B0B0E' },
    ...m.sv.map(p => ({ type: 'circle', center: p, r: 0.16, color: 'red', width: 2 })),
  ] })

const regionPlot = (m, c0, c1, box, step, caption) => ({ t: 'plot', caption, equal: true, axesAtZero: false, legend: false, height: 340,
  x: { min: box[0], max: box[1], step: 0.5, label: 'x₁' }, y: { min: box[2], max: box[3], step: 0.5, label: 'x₂' },
  series: [
    { type: 'cells', size: step, points: cells(rbf(m), box, step), colors: ['blue', 'orange'], opacity: 0.22 },
    { type: 'scatter', points: c0, color: 'blue', r: 3.6, opacity: 1, stroke: '#0B0B0E' },
    { type: 'scatter', points: c1, color: 'orange', r: 3.6, opacity: 1, stroke: '#0B0B0E' },
  ] })

